import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

export default function Signup() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [msg, setMsg] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMsg('');
    try {
      const res = await fetch(`http://127.0.0.1:8000/signup?email=${encodeURIComponent(email)}&password=${encodeURIComponent(password)}`, {
        method: 'POST',
      });

      if (res.ok) {
        setMsg('Compte créé! Vous pouvez maintenant vous connecter.');
        setTimeout(() => navigate('/login'), 1500);
      } else {
        const error = await res.json();
        setMsg(error.detail || 'Échec de l\'inscription');
      }
    } catch {
      setMsg('Erreur réseau');
    }
  };

  return (
    <div>
      <h2>Inscription</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="email"
          placeholder="Email"
          value={email}
          required
          onChange={e => setEmail(e.target.value)}
        /><br />
        <input
          type="password"
          placeholder="Mot de passe"
          value={password}
          required
          onChange={e => setPassword(e.target.value)}
        /><br />
        <button type="submit">S'inscrire</button>
      </form>
      <p style={{ color: 'red' }}>{msg}</p>
      <p>
        Déjà un compte? <Link to="/login">Se connecter</Link>
      </p>
    </div>
  );
}
